@Override public void onMessage(WebSocket webSocket, ByteBuffer buffer) {
  messagesRead++;
  if (messagesRead <= 2) {
    webSocket.request();
    return;
  }
  if (!buffer.hasRemaining()) {
    KubernetesClientException e = new KubernetesClientException("Received an empty message");
    serverThrowables.add(e);
    logger.debug("Protocol error", e);
    closeBothWays(webSocket, 1002, PROTOCOL_ERROR);
    return;
  }
  byte channel = buffer.get();
  if (channel < 0 || channel > 1) {
    KubernetesClientException e = new KubernetesClientException(String.format("Received a wrong channel from the remote socket: %s", channel));
    serverThrowables.add(e);
    logger.debug("Protocol error", e);
    closeBothWays(webSocket, 1002, PROTOCOL_ERROR);
  } else if (channel == 1) {
    KubernetesClientException e = new KubernetesClientException(String.format("Received an error from the remote socket %s", ExecWebSocketListener.toString(buffer)));
    serverThrowables.add(e);
    logger.debug("Server error", e);
    closeForwarder();
  } else {
    if (out != null) {
      serialExecutor.execute(() -> {
        try {
          while (buffer.hasRemaining()) {
            int written = out.write(buffer);
            if (written == 0) {
              Thread.sleep(50);
            }
          }
          webSocket.request();
        } catch (IOException | InterruptedException | NonWritableChannelException | ClosedChannelException | AsynchronousCloseException | ClosedByInterruptException e) {
          if (e instanceof InterruptedException) {
            Thread.currentThread().interrupt();
          }
          if (alive.get()) {
            clientThrowables.add(e);
            logger.debug("Error while forwarding data to the client", e);
            closeBothWays(webSocket, 1002, PROTOCOL_ERROR);
          }
        }
      });
    }
  }
}
